#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, threshold;
    scanf("%d %d", &n, &threshold);
    unordered_map<int, int> counts;
    counts.reserve(2 * n + 1);
    for (int i = 0; i < n; i++) {
        int sender, recipient, amount;
        scanf("%d %d %d", &sender, &recipient, &amount);
        counts[sender]++;
        // A self-transfer counts once for that log.
        if (recipient != sender) counts[recipient]++;
    }
    vector<int> out;
    for (auto &[u, c] : counts)
        if (c >= threshold) out.push_back(u);
    sort(out.begin(), out.end());
    string s = to_string(out.size()) + "\n";
    for (size_t i = 0; i < out.size(); i++) {
        if (i) s += ' ';
        s += to_string(out[i]);
    }
    puts(s.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), threshold = nextInt();
        HashMap<Integer, Integer> counts = new HashMap<>(4 * n + 16);
        for (int i = 0; i < n; i++) {
            int sender = nextInt(), recipient = nextInt();
            nextLong();
            counts.merge(sender, 1, Integer::sum);
            // A self-transfer counts once for that log.
            if (recipient != sender) counts.merge(recipient, 1, Integer::sum);
        }
        int[] out = counts.entrySet().stream().filter(e -> e.getValue() >= threshold)
                .mapToInt(Map.Entry::getKey).sorted().toArray();
        StringBuilder sb = new StringBuilder();
        sb.append(out.length).append('\n');
        for (int i = 0; i < out.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(out[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, threshold := readInt(), readInt()
	counts := make(map[int]int, 2*n)
	for i := 0; i < n; i++ {
		sender, recipient := readInt(), readInt()
		readInt()
		counts[sender]++
		// A self-transfer counts once for that log.
		if recipient != sender {
			counts[recipient]++
		}
	}
	out := []int{}
	for u, c := range counts {
		if c >= threshold {
			out = append(out, u)
		}
	}
	sort.Ints(out)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for i, u := range out {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(u))
	}
	w.WriteByte('\n')
}
